CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE TABLE "Reservations" (
    "Id"           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId"       INTEGER NOT NULL REFERENCES "Users" ("Id"),
    "HotelId"      INTEGER NOT NULL REFERENCES "Hotels" ("Id"),
    "RoomId"       INTEGER NOT NULL,
    "CheckInDate"  DATE NOT NULL,
    "CheckOutDate" DATE NOT NULL,
    "GuestCount"   INTEGER NOT NULL CHECK ("GuestCount" > 0),
    "Status"       TEXT NOT NULL CHECK ("Status" IN ('Pending', 'Confirmed', 'Cancelled')),
    "TotalPrice"   NUMERIC(10, 2) NOT NULL CHECK ("TotalPrice" >= 0),
    "CreatedAtUtc" TIMESTAMPTZ NOT NULL,
    "UpdatedAtUtc" TIMESTAMPTZ NOT NULL,
    CONSTRAINT "CK_Reservations_Dates" CHECK ("CheckInDate" < "CheckOutDate"),
    -- The room must belong to the reservation's hotel.
    CONSTRAINT "FK_Reservations_Room_Hotel" FOREIGN KEY ("RoomId", "HotelId") REFERENCES "Rooms" ("Id", "HotelId"),
    -- No overlapping active bookings for the same room (check-out day is free for the next check-in).
    CONSTRAINT "EX_Reservations_NoOverlap" EXCLUDE USING gist (
        "RoomId" WITH =,
        daterange("CheckInDate", "CheckOutDate", '[)') WITH &&
    ) WHERE ("Status" IN ('Pending', 'Confirmed'))
);

CREATE INDEX "IX_Reservations_UserId" ON "Reservations" ("UserId");
CREATE INDEX "IX_Reservations_RoomId" ON "Reservations" ("RoomId");
CREATE INDEX "IX_Reservations_HotelId" ON "Reservations" ("HotelId");

-- GuestCount must not exceed the room's capacity.
CREATE FUNCTION check_reservation_capacity() RETURNS trigger AS $$
BEGIN
    IF NEW."GuestCount" > (SELECT "Capacity" FROM "Rooms" WHERE "Id" = NEW."RoomId") THEN
        RAISE EXCEPTION 'GuestCount % exceeds capacity of room %', NEW."GuestCount", NEW."RoomId";
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "TR_Reservations_Capacity"
    BEFORE INSERT OR UPDATE OF "GuestCount", "RoomId" ON "Reservations"
    FOR EACH ROW EXECUTE FUNCTION check_reservation_capacity();

-- Seed: customers are users 3 and 4; rooms are looked up by (hotel, number).
INSERT INTO "Reservations" ("UserId", "HotelId", "RoomId", "CheckInDate", "CheckOutDate", "GuestCount", "Status", "TotalPrice", "CreatedAtUtc", "UpdatedAtUtc")
SELECT s.user_id, s.hotel_id, r."Id",  CURRENT_DATE + s.start_offset, CURRENT_DATE + s.start_offset + s.nights, s.guests, s.status,
       r."PricePerNight" * s.nights, now(), now()
FROM (VALUES
    (3, 1, '201',  -30, 3, 2, 'Confirmed'),   -- past stay
    (3, 1, '201',    7, 4, 2, 'Confirmed'),   -- upcoming
    (4, 1, '201',   11, 2, 1, 'Pending'),     -- back-to-back with the previous one
    (4, 2, '301',   14, 5, 4, 'Confirmed'),
    (3, 3, '101',    3, 2, 1, 'Pending'),
    (4, 4, '202',   20, 3, 2, 'Cancelled'),   -- cancelled: does not block the room
    (3, 4, '202',   21, 3, 2, 'Confirmed'),   -- same dates as the cancelled one
    (3, 5, '203',   30, 7, 3, 'Confirmed')
) AS s (user_id, hotel_id, room_number, start_offset, nights, guests, status)
JOIN "Rooms" r ON r."HotelId" = s.hotel_id AND r."RoomNumber" = s.room_number;
